python3 << 'PYEOF'
from docx import Document

doc = Document("/root/offer_letter_template.docx")

for ti, table in enumerate(doc.tables):
    print(f"Table {ti}: rows={len(table.rows)}, cols={len(table.columns)}")
    for ri, row in enumerate(table.rows):
        cells = row.cells
        print(f"  Row {ri} ({len(cells)} cells):")
        for ci, cell in enumerate(cells):
            for pi, para in enumerate(cell.paragraphs):
                text = para.text
                print(f"    Cell {ci}, P{pi}: '{text}'")
                # Also show runs
                for runi, run in enumerate(para.runs):
                    print(f"      Run {runi}: '{run.text}' bold={run.bold} italic={run.italic}")
