from docx import Document

doc = Document("/root/offer_letter_template.docx")

# Check runs in all paragraphs to see if any placeholders are split
for i, para in enumerate(doc.paragraphs):
    if para.text.strip():
        runs = [(r.text, r.bold, r.italic) for r in para.runs]
        if len(runs) > 1 or '{{' in para.text:
            print(f"P[{i}]: '{para.text}'")
            for ri, (text, bold, italic) in enumerate(runs):
                print(f"  Run {ri}: '{text}' bold={bold} italic={italic}")
